// processor module: adds scaffolder Template kind validation
backend.add(import('@backstage/plugin-catalog-backend-module-scaffolder-entity-model'));
backend.start();

import { coreServices, createBackendPlugin } from '@backstage/backend-plugin-api';
import { createRouter } from './router';

export const todoPlugin = createBackendPlugin({
  pluginId: 'todo',
  register(env) {
    env.registerInit({
      deps: { logger: coreServices.logger, httpRouter: coreServices.httpRouter },
      async init({ logger, httpRouter }) {
        httpRouter.use(await createRouter({ logger }));  // served at /api/todo
      },
    });
  },
});

